 assert(at("5fe50-1-3-0-1234-0",NODE+0x77,1)==2&&reg_a("5fe50-1-3-0-1234-0",1)==0&&at("5fe50-1-3-0-80000000-0",NODE+0x77,1)==4&&
  reg_a("5fe50-1-3-0-80000000-0",1)==0xc003f8U&&at("5fe50-1-3-1-1234-0",NODE+0x62,1)==0&&at("5fe50-1-3-0-1234-0",SP-4,4)==0x5feb2U);
 assert(at("5fe50-2-4-0-1234-0",NODE+0x77,1)==3&&reg_a("5fe50-2-4-0-1234-0",1)==0xc0041cU&&at("5fe50-4-4-0-1234-0",NODE+0x77,1)==5&&
  reg_a("5fe50-4-4-0-1234-0",1)==0xc00424U&&at("5fe50-3-0-1-1234-0",NODE+0x77,1)==6&&reg_a("5fe50-3-0-1-1234-0",1)==0xc00428U&&
  at("5fe50-3-0-0-1234-0",NODE+0x77,1)==3&&pc_of("5fe50-3-0-0-1234-0")==0x4a46c&&at("5fe50-6-0-1-1234-0",NODE+0x77,1)==0&&
  at("5fe50-6-0-1-1234-0",NODE+0x62,1)==0&&at("5fe50-6-0-0-1234-0",NODE+0x77,1)==6&&pc_of("5fe50-0-0-0-1234-0")==0x4a46c&&
  pc_of("5fe50-7-2-0-1234-0")==0x4a46c&&at("5fe50-7-2-0-1234-0",NODE+0x77,1)==7);
 assert(at("5fe92-80000000",NODE+0x77,1)==4&&at("5fe92-ffffffff",NODE+0x77,1)==4&&at("5fe92-7fffffff",NODE+0x77,1)==2&&at("5fe92-0",NODE+0x77,1)==2&&
  at("5fe92-0",NODE+0x62,1)==0);
 // 5ff90 step tables: index (2 * BYTE 77) & ff (ADD.B); 0 -> 77 = 0, 79 = 0, index 0.
